#include <stdio.h>
#include <stdlib.h>

int top = 0;
long stack[64];

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("ERROR\n");
        return 1;
    }

    for (int i = 1; i < argc; i++) {
        char *endptr;
        long num = strtol(argv[i], &endptr, 10);
        if (endptr == argv[i]) {
            // Operator
            if (top < 2) {
                printf("ERROR\n");
                return 1;
            }
            long b = stack[top - 1];
            long a = stack[top - 2];
            top -= 2;
            if (*argv[i] == '+') {
                stack[top++] = a + b;
            } else if (*argv[i] == '-') {
                stack[top++] = a - b;
            } else if (*argv[i] == '*') {
                stack[top++] = a * b;
            } else if (*argv[i] == '/') {
                if (b == 0) {
                    printf("ERROR\n");
                    return 1;
                }
                stack[top++] = a / b;
            }
        } else {
            // Number
            stack[top++] = num;
        }
    }

    if (top != 1) {
        printf("ERROR\n");
        return 1;
    }
    printf("%ld\n", stack[0]);
    return 0;
}
